// 지역 문자열에서 시/군/구를 찾아서 지역본부/지부 반환
function findJungingongBranch(regionStr) {
  if (!regionStr) return "";
  var matches = [];
  // 입력 정규화: 공백, _, -, 쉼표 등 구분자를 제거
  var normalized = (regionStr || "").replace(/[\s_\-,\.\/]/g, "");
  // 모든 키를 길이 내림차순 정렬 (긴 이름 우선 매칭 — 예: "광주광역시" → "광주시" 보다 먼저)
  var sortedKeys = Object.keys(JUNGINGONG_REGION_MAP).sort(function(a, b) {
    return b.length - a.length;
  });
  sortedKeys.forEach(function(key) {
    // _부산, _전북 등 중복 키 제거
    var pureKey = key.split("_")[0];
    if (!pureKey || pureKey.length < 2) return;
    // 1) 전체 키로 매칭 (예: "안산시", "광주시")
    var matched = normalized.indexOf(pureKey) >= 0;
    // 2) 시/군/구 접미사 제거하고 매칭 (예: "안산", "성남")
    if (!matched) {
      var keyWithoutSuffix = pureKey.replace(/(특별시|광역시|특별자치시|특별자치도|광역도|시|군|구)$/, "");
      if (keyWithoutSuffix.length >= 2) {
        // 단어 경계를 고려해 매칭 — 예: "안산" 검색 시 "고양"의 "양"과 매칭되지 않도록
        // 한글 입력은 단어 경계가 명확하지 않으므로, 그냥 indexOf로 처리
        matched = normalized.indexOf(keyWithoutSuffix) >= 0;
      }
    }
    if (matched) {
      JUNGINGONG_REGION_MAP[key].forEach(function(b) {
        if (matches.indexOf(b) < 0) matches.push(b);
      });
    }
  });
  return matches.join(", ");
}

// 매출액 포맷 함수
// 매출액 입력칸 정규화 — 숫자만 남기고 앞 0을 없앤 뒤 12자리(9,999억)까지만 받는다.
//  ⚠️ type="number" 를 쓰면 "3,002,936,000" 처럼 콤마째 붙여넣었을 때 브라우저가 값을 통째로
//     빈칸으로 만든다(무엇이 사라졌는지 화면에 안 보인다). 그래서 text + inputMode 로 받고
//     여기서 직접 거른다. parseInt 는 "3e9" 를 3 으로 읽어 버리므로 지수 표기도 여기서 막힌다.
//  ⚠️ 자릿수를 줄이지 않는다 — 12자리는 상한이지 반올림이 아니다. 넘겨 친 자리만 안 받는다.
var REVENUE_MAX_DIGITS = 12;
function normalizeRevenueInput(raw) {
  var d = String(raw === null || raw === undefined ? "" : raw).replace(/[^0-9]/g, "").replace(/^0+(?=[0-9])/, "");
  return d.slice(0, REVENUE_MAX_DIGITS);
}
const formatRevenue = (val) => {
  if (!val && val !== 0) return '-';
  const n = typeof val === 'string' ? parseInt(val.replace(/[^0-9]/g, '')) : val;
  if (isNaN(n) || n === 0) return '-';
  // 한글 단위 분해: 조 / 억 / 만
  var parts = [];
  var jo = Math.floor(n / 1000000000000);
  var eok = Math.floor((n % 1000000000000) / 100000000);
  var man = Math.floor((n % 100000000) / 10000);
  var won = n % 10000;
  if (jo > 0) parts.push(jo + '조');
  // 억 단위 - 1000 이상이면 천억 표시
  if (eok > 0) {
    if (eok >= 1000) {
      var cheonEok = Math.floor(eok / 1000);
      var nam = eok % 1000;
      var eokStr = cheonEok + '천';
      if (nam > 0) eokStr += nam;
      parts.push(eokStr + '억');
    } else {
      parts.push(eok + '억');
    }
  }
  // 만 단위 - 1000 이상이면 천만 표시
  if (man > 0) {
    if (man >= 1000) {
      var cheonMan = Math.floor(man / 1000);
      var namMan = man % 1000;
      var manStr = cheonMan + '천';
      if (namMan > 0) {
        var baekMan = Math.floor(namMan / 100);
        var restMan = namMan % 100;
        if (baekMan > 0) manStr += baekMan + '백';
        if (restMan > 0) manStr += restMan;
      }
      parts.push(manStr + '만');
    } else {
      parts.push(man + '만');
    }
  }
  // 만 미만 나머지 — 천 단위까지만 보여준다(3,002,936,000 → "30억 293만 6천").
  //  예전엔 통째로 버려서 "30억 293만"으로 보였다. 대부분의 매출은 나머지가 0이라 표시가 그대로다.
  if (won >= 1000) parts.push(Math.floor(won / 1000) + '천');
  return parts.length > 0 ? parts.join(' ') : n.toLocaleString();
};

// ── 아이콘 ────────────────────────────────────────────────────────────────────

// fflate(압축 해제) 지연 로더 — 한셀/한컴오피스로 만든 xlsx 정규화 폴백 전용.
//  로컬 번들에서 동적 import(같은 오리진 청크, 외부 CDN 불필요) + 폴백 경로에서만 로드되어
//  표준 엑셀 업로드에서는 절대 내려받지 않는다.
async function ensureFflate() {
  return await import("fflate");
}

// 한셀(한컴오피스)로 저장한 xlsx는 표준 엑셀과 달리
//  (1) 모든 요소 태그에 spreadsheetml 네임스페이스 접두사(<x:row>, <x:c>, <x:si> …)를 붙이고
//  (2) 리치텍스트/스타일에 haansoft 전용 확장(<hs:size> 등)을 mc:AlternateContent 블록으로 섞는다.
//  SheetJS(정규식 파서)는 이 둘 때문에 셀 데이터를 하나도 못 읽거나 "Unrecognized rich format" 예외로 실패한다.
//  → 데이터(셀 값)만 필요하므로, XML을 표준형으로 정규화한다:
//    · mc:AlternateContent → 표준 대체본(mc:Fallback) 내용으로 치환(hs 확장 제거)
//    · 남은 haansoft(hs:) 요소/속성 제거(안전망)
//    · spreadsheetml 접두사 제거 + 기본 네임스페이스로 승격(SheetJS는 루트 xmlns를 요구)
function normalizeHancellXml(xml) {
  // 1) 마크업 호환성 블록을 표준 대체본으로 치환 (호환 소비자의 표준 처리 방식)
  xml = xml.replace(/<mc:AlternateContent\b[\s\S]*?<\/mc:AlternateContent>/g, function(block) {
    var fb = block.match(/<mc:Fallback\b[^>]*>([\s\S]*?)<\/mc:Fallback>/);
    return fb ? fb[1] : "";
  });
  // 2) 혹시 남은 haansoft 확장 요소/속성 제거
  xml = xml
    .replace(/<hs:[A-Za-z0-9]+\b[^>]*\/>/g, "")
    .replace(/<hs:[A-Za-z0-9]+\b[^>]*>[\s\S]*?<\/hs:[A-Za-z0-9]+>/g, "")
    .replace(/\s+hs:[A-Za-z0-9]+="[^"]*"/g, "");
  // 3) spreadsheetml 네임스페이스 접두사 제거 + 기본 네임스페이스로 승격
  var m = xml.match(/xmlns:([A-Za-z0-9]+)="http:\/\/schemas\.openxmlformats\.org\/spreadsheetml\/2006\/main"/);
  if (m) {
    var p = m[1];
    xml = xml
      .replace(new RegExp("<" + p + ":", "g"), "<")
      .replace(new RegExp("</" + p + ":", "g"), "</")
      .replace(new RegExp("xmlns:" + p + "=", "g"), "xmlns=");
  }
  return xml;
}

// 워크북에 실제 데이터 셀이 하나라도 있는지(!로 시작하는 메타 키 제외)
function workbookHasCells(wb) {
  return (wb && wb.SheetNames || []).some(function(n) {
    var ws = wb.Sheets[n];
    return ws && Object.keys(ws).some(function(k) { return k.charAt(0) !== "!"; });
  });
}

// 업로드된 xlsx를 최대한 안전하게 읽는다.
//  · 먼저 표준 읽기를 시도(정상 엑셀은 여기서 끝 — fflate 미로드, 성능·동작 변화 없음).
//  · 셀이 하나도 안 잡히면(한셀/한컴 파일 의심) XML을 정규화해 재시도.
async function readUploadedWorkbook(data, opts) {
  var XLSX = await ensureXLSX();
  var wb;
  try { wb = XLSX.read(data, opts); } catch (e) { wb = null; }
  if (wb && workbookHasCells(wb)) return wb;
  // 폴백: 한셀/한컴 네임스페이스 파일 정규화 후 재시도
  try {
    var fflate = await ensureFflate();
    var u8 = data instanceof Uint8Array ? data : new Uint8Array(data);
    var files = fflate.unzipSync(u8);
    var td = new TextDecoder(), te = new TextEncoder();
    var changed = false;
    Object.keys(files).forEach(function(name) {
      if (!/\.xml$/i.test(name)) return;
      var s = td.decode(files[name]);
      if (s.indexOf("spreadsheetml/2006/main") < 0 && s.indexOf("haansoft") < 0 && s.indexOf("<mc:AlternateContent") < 0) return;
      var fixed = normalizeHancellXml(s);
      if (fixed !== s) { files[name] = te.encode(fixed); changed = true; }
    });
    if (changed) {
      var clean = fflate.zipSync(files);
      var wb2 = XLSX.read(clean, opts);
      if (wb2 && workbookHasCells(wb2)) return wb2;
    }
  } catch (e) { /* 정규화 실패 시 원본 결과로 진행 */ }
  if (wb) return wb;
  throw new Error("엑셀 파일을 읽을 수 없습니다.");
}

// 기업현황표(xlsx) 파싱 공용 함수 - 신규등록/상세패널 양쪽에서 사용
async function parseHyeonhwangpyo(file) {
  var XLSX = await ensureXLSX();
  var data = await file.arrayBuffer();
  var wb = await readUploadedWorkbook(data, { type: "array", cellDates: true });
  var sheetName = wb.SheetNames.find(function(n) { return n.indexOf("기업개요") >= 0; }) || wb.SheetNames[0];
  var ws = wb.Sheets[sheetName];
  var rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: null });
  var getCell = function(r, c) {
    if (!rows[r]) return "";
    var v = rows[r][c];
    if (v === null || v === undefined) return "";
    if (v instanceof Date) { return v.getFullYear() + "-" + String(v.getMonth() + 1).padStart(2, "0") + "-" + String(v.getDate()).padStart(2, "0"); }
    return String(v).trim();
  };
  // 숫자 못 뽑은 칸 목록 + 숫자 칸 원문 보존 (신규 양식 파서와 같은 규칙)
  var issues = [];
  var addIssue = function(label, r) { issues.push({ label: label, raw: (r && r.raw) || "", reason: (r && r.reason) || "확인 필요" }); };
  // 값은 넣었지만 단위를 코드가 판단한 칸 — 빨간 "확인 필요"와 달리 파란 안내로 보여준다(무엇을 어떻게 읽었는지 밝힌다)
  var notes = [];
  var addNote = function(label, raw, note) { notes.push({ label: label, raw: String(raw == null ? "" : raw).trim(), note: note }); };
  var rawNotes = [];
  var keepRaw = function(label, raw) { if (cellHasContext(raw)) rawNotes.push(label + ": " + String(raw).trim()); };
  // 구 양식은 매출칸 머리글에 단위가 없다(라벨 "매출 (2025년)"의 괄호는 연도지 단위가 아니다).
  //  → 머리글은 넘기지 않고, 9자리(1억) 이상일 때만 원으로 확정한다(resolveAmountCell ③).
  var parseRevenue = function(s, label) {
    if (!s) return "";
    var r = resolveAmountCell(s, "");
    keepRaw(label, s);
    if (r.ok) { if (r.note) addNote(label, s, r.note); return Math.round(r.value); }
    addIssue(label, r);
    return "";
  };
  var parseCredit = function(s) {
    if (!s) return { kcb: "", nice: "" };
    var kcbMatch = String(s).match(/KCB\s*([0-9]+)/i);
    var niceMatch = String(s).match(/NICE\s*([0-9]+)/i);
    return { kcb: kcbMatch ? kcbMatch[1] : "", nice: niceMatch ? niceMatch[1] : "" };
  };
  var parseRepAndPhone = function(s) {
    if (!s) return { rep: "", phone: "" };
    var parts = String(s).split("/").map(function(x) { return x.trim(); });
    var rep = parts[0] || "";
    var phone = parts[1] || "";
    rep = rep.replace(/대표(이사)?$/, "").trim();
    phone = phone.replace(/[^0-9-]/g, "");
    return { rep: rep, phone: phone };
  };
  var parseFoundedDate = function(s) {
    if (!s) return { year: "", month: "" };
    var str = String(s);
    var match = str.match(/(\d{4})[-/.년\s]*(\d{1,2})/);
    if (match) return { year: match[1], month: parseInt(match[2]) };
    return { year: "", month: "" };
  };
  var parseRegion = function(addr) {
    if (!addr) return "";
    var s = String(addr).replace(/^\s*[([]?\s*\d{5}\s*[)\]]?\s*/, "");   // 앞에 붙은 우편번호 제거
    var doMap = { "서울특별시": "서울", "서울": "서울", "부산광역시": "부산", "부산": "부산", "대구광역시": "대구", "대구": "대구", "인천광역시": "인천", "인천": "인천", "광주광역시": "광주", "광주": "광주", "대전광역시": "대전", "대전": "대전", "울산광역시": "울산", "울산": "울산", "세종특별자치시": "세종", "세종": "세종", "경기도": "경기", "강원도": "강원", "강원특별자치도": "강원", "충청북도": "충북", "충북": "충북", "충청남도": "충남", "충남": "충남", "전라북도": "전북", "전북": "전북", "전북특별자치도": "전북", "전라남도": "전남", "전남": "전남", "경상북도": "경북", "경북": "경북", "경상남도": "경남", "경남": "경남", "제주특별자치도": "제주", "제주도": "제주", "제주": "제주" };
    var firstWord = s.split(/\s+/)[0];
    var doName = doMap[firstWord] || firstWord;
    var secondWord = s.split(/\s+/)[1] || "";
    var siGuGun = secondWord.replace(/시$|군$|구$/, "");
    return doName + (siGuGun ? "_" + siGuGun : "");
  };
  var updates = {};
  var auto = {};
  var name = getCell(2, 2);
  if (name) { updates.name = name; auto.name = true; }
  var bizNum = getCell(2, 8);
  if (bizNum) { updates.business_number = bizNum; auto.business_number = true; }
  var repPhone = parseRepAndPhone(getCell(3, 2));
  if (repPhone.rep) { updates.representative = repPhone.rep; auto.representative = true; }
  if (repPhone.phone) { updates.phone = repPhone.phone; auto.phone = true; }
  var addr = getCell(4, 2);
  var region = parseRegion(addr);
  if (region) { updates.region = region; auto.region = true; }
  var industry = getCell(5, 2);
  if (industry) { updates.industry = industry; auto.industry = true; }
  var emp = getCell(5, 8);
  if (emp && emp !== "없음" && emp !== "추후") {
    // "2명" · "1명/2명(현재)"처럼 값이 여럿이면 첫 번째만 쓰고 원문은 메모에 보존
    var empR = extractLeadingNumber(emp);
    if (empR.ok) { updates.employee_count = Math.round(empR.num); auto.employee_count = true; }
    else addIssue("직원현황", empR);
    keepRaw("직원현황", emp);
  } else if (emp === "없음") { updates.employee_count = 0; auto.employee_count = true; }
  var credit = parseCredit(getCell(6, 2));
  if (credit.kcb) { updates.credit_score_kcb = credit.kcb; auto.credit_score_kcb = true; }
  if (credit.nice) { updates.credit_score_nice = credit.nice; auto.credit_score_nice = true; }
  var founded = parseFoundedDate(getCell(6, 8));
  if (founded.year) { updates.founded_year = founded.year; auto.founded_year = true; }
  if (founded.month) { updates.founded_month = founded.month; auto.founded_month = true; }
  var rev2025 = parseRevenue(getCell(12, 2), "2025년 매출");
  var rev2024 = parseRevenue(getCell(12, 6), "2024년 매출");
  var rev2023 = parseRevenue(getCell(12, 10), "2023년 매출");
  if (rev2025) { updates.revenue_2025 = rev2025; auto.revenue_2025 = true; }
  if (rev2024) { updates.revenue_2024 = rev2024; auto.revenue_2024 = true; }
  if (rev2023) { updates.revenue_2023 = rev2023; auto.revenue_2023 = true; }
  var bizTypeOld = inferBusinessType(name, bizNum);
  if (bizTypeOld) { updates.business_type = bizTypeOld.business_type; updates.type = bizTypeOld.type; }
  var loans = [];
  // 구분은 미분류로 넣는다 — 현황표에는 채무자가 누구인지 적는 칸이 없어 회사 유형으로 추정하면
  // 대표자 개인 채무가 법인 부채비율에 섞여 들어간다. 담당자가 화면에서 지정한다(미분류 건수 배지로 안내).
  for (var lr = 17; lr <= 23; lr++) {
    var inst = getCell(lr, 2), amt = getCell(lr, 5), bank = getCell(lr, 7), sdate = getCell(lr, 8), edate = getCell(lr, 10);
    if (inst || amt || bank || sdate || edate) { loans.push({ inst: inst, amount: amt, bank: bank, start: sdate, end: edate, kind: "" }); }
  }
  if (loans.length > 0) { updates.loans = loans; auto.loans = true; }
  var infoItems = [];
  var addInfo = function(label, val) { if (val && String(val).trim()) infoItems.push({ label: label, value: String(val).trim() }); };
  addInfo("대표자 생년월일", getCell(3, 8));
  addInfo("26년 현재/예상 매출", getCell(11, 2));
  addInfo("법인 자본금", getCell(11, 8));
  addInfo("회생 및 파산 이력", getCell(8, 8));
  addInfo("재창업 조건 (폐업이력)", getCell(15, 2));
  addInfo("기업인증", [getCell(13, 10), getCell(14, 8), getCell(15, 8)].filter(function(x) { return x && x !== "노란우산공제, 제로페이" && x !== "내일채움"; }).join(", "));
  addInfo("특허 및 상표권", getCell(14, 6));
  addInfo("연구소", getCell(14, 2));
  addInfo("수출실적", getCell(13, 2));
  addInfo("노란우산공제", getCell(14, 10));
  addInfo("세금/금융 연체", getCell(13, 6));
  addInfo("추가 사업자 여부", getCell(8, 2));
  addInfo("주요취급품목", getCell(7, 2));
  addInfo("대표 결혼 유/무", getCell(7, 8));
  addInfo("대표자 거주지 부동산", getCell(9, 2));
  addInfo("사업장 부동산 유무", getCell(9, 8));
  addInfo("대표이사 자산현황", getCell(10, 2));
  addInfo("사업장 부동산 현황", getCell(10, 8));
  addInfo("세무사 연락처", getCell(4, 8));
  addInfo("필요자금 사용용도", getCell(26, 2));
  if (infoItems.length > 0) { updates.company_info = infoItems; auto.company_info = true; }
  var bigoMemo = getCell(28, 2) || getCell(29, 2) || getCell(30, 2);
  var memoParts = [];
  if (bigoMemo) memoParts.push(bigoMemo);
  if (rawNotes.length) memoParts.push("[원문 보존]\n" + rawNotes.join("\n"));
  if (memoParts.length) { updates.company_info_memo = memoParts.join("\n\n"); auto.company_info_memo = true; }
  return { updates: updates, auto: auto, issues: issues, notes: notes };
}

// SheetJS(XLSX) 라이브러리 로더 - 여러 파서에서 공용.
//  로컬 번들에서 동적 import(같은 오리진 청크, 외부 CDN 불필요) + xlsx 파싱이 필요할 때만
//  로드되는 지연 로딩(별도 청크). ESM 네임스페이스/CJS default 어느 쪽이든 .read를 가진 객체 반환.
async function ensureXLSX() {
  var mod = await import("xlsx");
  return (mod && mod.read) ? mod : ((mod && mod.default) ? mod.default : mod);
}

// 라벨 기반 범용 시트지 파서 - 표준 기업현황표가 아닌 임의 양식(상담 시트지 등)에서
//  · 인식되는 항목 → 기업정보 필드 자동 채움 (updates/auto)
//  · 나머지 모든 내용 → 소통내역에 넣을 텍스트로 정리 (commText)
function parseSheetGeneric(rows) {
  var cellStr = function(v) {
    if (v === null || v === undefined) return "";
    if (v instanceof Date) { return v.getFullYear() + "-" + String(v.getMonth() + 1).padStart(2, "0") + "-" + String(v.getDate()).padStart(2, "0"); }
    return String(v).trim();
  };
  var norm = function(s) { return String(s || "").replace(/\s/g, "").replace(/[:：\-()（）]/g, ""); };
  // 맨 앞 숫자만 — "34명(2026.1 기준)/36명"처럼 맥락이 붙어도 첫 값만 쓴다(전부 이어붙이면 엉뚱한 숫자가 된다)
  var digitsOnly = function(s) { var r = extractLeadingNumber(s); return r.ok ? String(Math.round(r.num)) : ""; };
  var parseRegionG = function(addr) {
    if (!addr) return "";
    var s = String(addr).replace(/^\s*[([]?\s*\d{5}\s*[)\]]?\s*/, "");   // 앞에 붙은 우편번호 제거
    var doMap = { "서울특별시": "서울", "서울": "서울", "부산광역시": "부산", "부산": "부산", "대구광역시": "대구", "대구": "대구", "인천광역시": "인천", "인천": "인천", "광주광역시": "광주", "광주": "광주", "대전광역시": "대전", "대전": "대전", "울산광역시": "울산", "울산": "울산", "세종특별자치시": "세종", "세종": "세종", "경기도": "경기", "경기": "경기", "강원도": "강원", "강원특별자치도": "강원", "강원": "강원", "충청북도": "충북", "충북": "충북", "충청남도": "충남", "충남": "충남", "전라북도": "전북", "전북": "전북", "전북특별자치도": "전북", "전라남도": "전남", "전남": "전남", "경상북도": "경북", "경북": "경북", "경상남도": "경남", "경남": "경남", "제주특별자치도": "제주", "제주도": "제주", "제주": "제주" };
    var firstWord = s.split(/\s+/)[0];
    var doName = doMap[firstWord] || firstWord;
    var secondWord = s.split(/\s+/)[1] || "";
    var siGuGun = secondWord.replace(/시$|군$|구$/, "");
    return doName + (siGuGun ? "_" + siGuGun : "");
  };
  var parseFoundedG = function(s) {
    var m = String(s || "").match(/(\d{4})[-/.년\s]*(\d{1,2})?/);
    if (m) return { year: m[1], month: m[2] ? parseInt(m[2], 10) : "" };
    return { year: "", month: "" };
  };
  // 라벨(정규화된 키) → 회사 필드 매핑 규칙
  var MATCHERS = [
    { field: "name", keys: ["업체명", "회사명", "기업명", "상호", "상호명", "법인명", "사업체명"] },
    { field: "representative", keys: ["대표자", "대표", "대표이사", "대표자명", "대표이사명", "성명", "대표성명"], clean: function(v) { return String(v).replace(/대표(이사)?$/, "").trim(); } },
    { field: "phone", keys: ["연락처", "전화", "전화번호", "휴대폰", "핸드폰", "연락", "대표번호", "휴대전화", "핸드폰번호"], clean: function(v) { return String(v).replace(/[^0-9-]/g, ""); } },
    { field: "business_number", keys: ["사업자등록번호", "사업자번호", "사업자", "등록번호"] },
    { field: "region", keys: ["주소", "소재지", "사업장주소", "사업장소재지", "본점소재지", "사업장", "사업장위치"], transform: parseRegionG },
    { field: "industry", keys: ["업종", "업태", "종목", "주업종", "업종업태", "사업내용", "주요업종"] },
    { field: "employee_count", keys: ["직원수", "종업원수", "상시근로자", "근로자수", "고용인원", "인원", "종업원", "직원"], clean: digitsOnly },
    { field: "credit_score_kcb", keys: ["kcb", "kcb점수", "올크레딧"], clean: digitsOnly },
    { field: "credit_score_nice", keys: ["nice", "nice점수", "나이스"], clean: digitsOnly },
    { field: "founded", keys: ["설립일", "설립연도", "설립년도", "개업일", "창업일", "설립", "설립일자", "개업연월일"], transform: parseFoundedG },
  ];
  var lookup = {};
  MATCHERS.forEach(function(m) { m.keys.forEach(function(k) { lookup[norm(k).toLowerCase()] = m; }); });

  // 각 행을 (라벨, 값) 쌍으로 정리 — 2열 폼(라벨|값) 및 다열 모두 대응
  var pairs = [];
  rows.forEach(function(row) {
    if (!row) return;
    var nonEmpty = [];
    row.forEach(function(c) { var v = cellStr(c); if (v) nonEmpty.push(v); });
    if (nonEmpty.length === 0) return;
    if (nonEmpty.length === 1) { pairs.push({ label: "", value: nonEmpty[0] }); }
    else { pairs.push({ label: nonEmpty[0], value: nonEmpty.slice(1).join(" ") }); }
  });

  var updates = {}, auto = {};
  var leftover = [];
  pairs.forEach(function(p) {
    var key = norm(p.label).toLowerCase();
    var m = p.label ? lookup[key] : null;
    if (m && p.value) {
      if (m.field === "founded") {
        var f = m.transform(p.value);
        if (f.year && !updates.founded_year) { updates.founded_year = f.year; auto.founded_year = true; }
        if (f.month && !updates.founded_month) { updates.founded_month = f.month; auto.founded_month = true; }
        return;
      }
      var val = m.clean ? m.clean(p.value) : (m.transform ? m.transform(p.value) : p.value);
      if (val && !updates[m.field]) { updates[m.field] = val; auto[m.field] = true; return; }
    }
    // 인식 안 된 내용 → 소통내역 텍스트로 보존
    if (p.label && p.value) leftover.push(p.label + ": " + p.value);
    else if (p.value) leftover.push(p.value);
  });

  // 법인/개인 유형 추정
  var bizTypeG = inferBusinessType(updates.name, updates.business_number);
  if (bizTypeG) { updates.business_type = bizTypeG.business_type; updates.type = bizTypeG.type; }

  return { updates: updates, auto: auto, commText: leftover.join("\n") };
}

// ── 신규 통합 기업현황표(시트명 "정보시트") 파서 ──────────────────────────────
//  구 양식(기업개요 시트)은 parseHyeonhwangpyo가 담당한다. 이 함수는 건드리지 않는다.
//
//  왜 별도 파서인가: 신규 양식은 시트명이 "기업개요"가 아니라 라벨 기반 범용 파서로 넘어가
//  4개 항목만 인식되고 값까지 오염됐다(2026-07-27 진단). 구 양식과 레이아웃이 완전히 다르다.
//
//  왜 행 번호를 고정하지 않는가: 이번 장애의 원인이 바로 고정 좌표였다.
//  라벨 텍스트로 위치를 찾아 값 셀을 읽으므로, 행이 추가/삭제돼도 깨지지 않는다.
//
//  병합 구조(실측): 한 행에 좌·우 두 쌍. 라벨 c0 → 값 c3 / 라벨 c6 → 값 c9.
function parseHyeonhwangpyoV2(rows) {
  var cellStr = function(v) {
    if (v === null || v === undefined) return "";
    if (v instanceof Date) { return v.getFullYear() + "-" + String(v.getMonth() + 1).padStart(2, "0") + "-" + String(v.getDate()).padStart(2, "0"); }
    return String(v).trim();
  };
  // 라벨 정규화 — 공백/구두점/★ 제거. 양식이 "부채총계 (원)"처럼 단위를 붙여도 같은 키가 되게 한다.
  var norm = function(s) { return String(s || "").replace(/\s/g, "").replace(/[:：\-()（）·.,/★]/g, "").toLowerCase(); };

  // 라벨 인덱스: 정규화라벨 → { r: 행, c: 값이 있는 열 }
  var idx = {};
  var LABEL_COLS = [[0, 3], [6, 9]];
  rows.forEach(function(row, r) {
    if (!row) return;
    LABEL_COLS.forEach(function(pair) {
      var lab = norm(row[pair[0]]);
      if (lab && !Object.prototype.hasOwnProperty.call(idx, lab)) idx[lab] = { r: r, c: pair[1] };
    });
  });
  var get = function(label) {
    var k = idx[norm(label)];
    if (!k || !rows[k.r]) return "";
    return cellStr(rows[k.r][k.c]);
  };

  var updates = {}, auto = {};
  var setF = function(field, val) { if (val !== "" && val != null) { updates[field] = val; auto[field] = true; } };

  // 숫자 못 뽑은 칸 목록 — 0으로 채우지 않고 비워둔 뒤 화면에 그대로 보여준다(콘솔 안 열어도 보이게)
  var issues = [];
  var addIssue = function(label, r) { issues.push({ label: label, raw: (r && r.raw) || "", reason: (r && r.reason) || "확인 필요" }); };
  // 값은 넣었지만 단위를 코드가 판단한 칸 — 빨간 "확인 필요"와 달리 파란 안내로 보여준다(무엇을 어떻게 읽었는지 밝힌다)
  var notes = [];
  var addNote = function(label, raw, note) { notes.push({ label: label, raw: String(raw == null ? "" : raw).trim(), note: note }); };
  // 숫자 칸의 원문 보존 — 숫자 컬럼에 들어가면서 사라질 맥락을 메모에 남긴다(스크립트 작성 재료)
  var rawNotes = [];
  var keepRaw = function(label, raw) { if (cellHasContext(raw)) rawNotes.push(label + ": " + String(raw).trim()); };

  // ── 1. 기업 기본 ──────────────────────────────────────────────────────
  setF("name", get("기업체명"));
  setF("business_number", get("사업자등록번호"));
  // 법인/개인 판정은 여기서 먼저 한다 — 아래 기대출 구분 자동지정이 이 값을 쓴다
  var bizType = inferBusinessType(updates.name, updates.business_number);
  if (bizType) { updates.business_type = bizType.business_type; updates.type = bizType.type; }
  setF("representative", String(get("대표자명")).replace(/대표(이사)?$/, "").trim());
  var phone = String(get("대표자 연락처")).replace(/[^0-9-]/g, "");
  setF("phone", phone);
  var addr = get("사업장 주소");
  if (addr) {
    var doMap = { "서울특별시": "서울", "부산광역시": "부산", "대구광역시": "대구", "인천광역시": "인천", "광주광역시": "광주", "대전광역시": "대전", "울산광역시": "울산", "세종특별자치시": "세종", "경기도": "경기", "강원도": "강원", "강원특별자치도": "강원", "충청북도": "충북", "충청남도": "충남", "전라북도": "전북", "전북특별자치도": "전북", "전라남도": "전남", "경상북도": "경북", "경상남도": "경남", "제주특별자치도": "제주", "제주도": "제주" };
    // 작성본에 우편번호가 앞에 붙는다("(50315) 경상남도 창녕군 …") → 떼고 시·도부터 읽는다
    var w = String(addr).replace(/^\s*[([]?\s*\d{5}\s*[)\]]?\s*/, "").split(/\s+/);
    var doName = doMap[w[0]] || w[0];
    var siGuGun = (w[1] || "").replace(/시$|군$|구$/, "");
    setF("region", doName + (siGuGun ? "_" + siGuGun : ""));
  }
  setF("industry", get("업태 / 종목"));
  // 상시근로자: "34명(2026.1 기준)/36명(2026.5 KODATA조회)" → 첫 번째 값 34, 원문은 메모에 보존
  var empRaw = get("상시근로자 (현재)");
  if (String(empRaw).trim()) {
    var empR = extractLeadingNumber(empRaw);
    if (empR.ok) setF("employee_count", Math.round(empR.num));
    else addIssue("상시근로자", empR);
    keepRaw("상시근로자", empRaw);
  }
  var fdRaw = get("설립일자");
  var fd = String(fdRaw).match(/(\d{4})[-/.년\s]*(\d{1,2})?/);
  if (fd) { setF("founded_year", fd[1]); if (fd[2]) setF("founded_month", parseInt(fd[2], 10)); }
  else if (String(fdRaw).trim()) addIssue("설립일자", { raw: fdRaw, reason: "연도를 찾지 못함" });
  [["credit_score_kcb", "신용 KCB (점)", "신용 KCB"], ["credit_score_nice", "신용 NICE (점)", "신용 NICE"]].forEach(function(c) {
    var raw = get(c[1]);
    if (!String(raw).trim()) return;
    var r = extractLeadingNumber(raw);
    if (r.ok) { setF(c[0], Math.round(r.num)); keepRaw(c[2], raw); }
    else addIssue(c[2], r);
  });

  // ── 3. 매출 추이 — 연도칸은 매년 수정되므로 '읽어서' 매핑한다(고정 가정 금지) ──
  var yearRow = idx[norm("연도")];
  var profitInfo = [];
  if (yearRow) {
    // 단위 확정은 resolveAmountCell 한 곳에 있다: 셀에 적힌 단위("28,886백만원") > 머리글 "(원)" > 9자리↑.
    // 담당자가 셀에 직접 쓴 단위가 언제나 이기므로, 머리글을 읽어도 옛 사고(6,652를 6,652원으로 저장)는 안 난다.
    var hdrRow = rows[yearRow.r] || [];
    var findHdr = function(re) {
      for (var hc = 0; hc < hdrRow.length; hc++) { var t = cellStr(hdrRow[hc]); if (t && re.test(t)) return t; }
      return "";
    };
    var amtHdr = findHdr(/매출/), profitHdr = findHdr(/순이익/);   // 머리글 칸 자체를 찾는다 — 열 위치가 밀려도 따라간다
    for (var r = yearRow.r + 1; r < rows.length; r++) {
      var row = rows[r];
      if (!row) continue;
      var head = cellStr(row[0]);
      if (!head) continue;
      if (/^\d+\s*\./.test(head)) break;              // 다음 섹션 헤더 만나면 종료
      var amt = cellStr(row[3]);
      var profit = cellStr(row[6]), bigo = cellStr(row[9]);
      // 금액 말고 담당자가 적은 순이익·비고도 버리지 않는다(스크립트 재료)
      if (amt || profit || bigo) {
        var line = head + " 매출액: " + (amt || "-")
          + (profit ? " / 당기순이익: " + profit : "")
          + (bigo ? " / 비고: " + bigo : "");
        if (cellHasContext(amt) || profit || bigo) rawNotes.push(line);
      }
      var ym = head.match(/(\d{4})/);
      var isForecast = /예상/.test(head);             // 예상치는 실적으로 담지 않는다
      // 당기순이익도 (원) 단위 칸이라 매출액과 같은 규칙으로 확정해 기업정보에 남긴다.
      //  ⚠️ 숫자가 아예 없는 칸("-", "적자")은 원문이 위 rawNotes에 보존되므로 조용히 넘긴다.
      if (profit && ym && !isForecast) {
        var pR = resolveAmountCell(profit, profitHdr);
        if (pR.ok) {
          profitInfo.push({ label: head + " 당기순이익", value: Math.round(pR.value).toLocaleString() + "원" });
          if (pR.note) addNote(head + " 당기순이익", profit, pR.note);
        } else if (pR.reason === "단위 확인 필요") addIssue(head + " 당기순이익", pR);
      }
      if (!amt) continue;
      if (!ym) continue;
      var yr = ym[1];
      if (isForecast) continue;
      var field = /상반기/.test(head) ? "revenue_2026_h1"
        : (yr === "2025" ? "revenue_2025" : (yr === "2024" ? "revenue_2024" : (yr === "2023" ? "revenue_2023" : "")));
      if (!field) continue;
      var amtR = resolveAmountCell(amt, amtHdr);
      if (amtR.ok) {
        setF(field, Math.round(amtR.value));
        if (amtR.note) addNote(head + " 매출액", amt, amtR.note);
      } else addIssue(head + " 매출액", amtR);        // 실패해도 이 칸만 비우고 나머지는 정상 저장
    }
  }

  // ── 7. 기대출 현황 → loans 배열 ───────────────────────────────────────
  //  열: c0 구분 / c2 기관·상품 / c5 금액(원) / c7 은행 / c8 실행일 / c9 만기일 / c10 잔액(원)
  var loanHdr = null;
  rows.forEach(function(row, r) {
    if (loanHdr || !row) return;
    if (norm(row[0]) === norm("구분") && norm(row[2]) === norm("기관 / 상품")) loanHdr = r;
  });
  if (loanHdr != null) {
    var loans = [];
    for (var lr = loanHdr + 1; lr < rows.length; lr++) {
      var lrow = rows[lr];
      if (!lrow) continue;
      var c0 = cellStr(lrow[0]);
      if (/^\d+\s*\./.test(c0)) break;                            // 다음 섹션
      if (/신규\s*융자|카드론|현금서비스/.test(c0)) break;           // 부가 항목 구간 시작(위에서 company_info로 따로 담는다)
      var inst = cellStr(lrow[2]), amount = cellStr(lrow[5]), bank = cellStr(lrow[7]);
      var start = cellStr(lrow[8]), end = cellStr(lrow[9]), balance = cellStr(lrow[10]);
      if (!inst && !amount && !bank && !start && !end && !balance) continue;   // 빈 행
      // "합계"가 들어간 행이 전부 소계는 아니다.
      //  · 순수 소계 행: 기관·상품(c2)이 비어 있고 금액만 있다 → 개별 행과 이중계상되므로 버린다
      //  · "캐피탈·리스·보증 6건 합계"처럼 여러 건을 한 줄로 묶어 적은 행: 기관·상품이 채워져 있다
      //    → 실제 대출이므로 담는다(예전엔 이 행이 통째로 빠져 부채가 누락됐다)
      //  ※ 여신정보 문서 파서의 소계 제외(isSubtotalRow)는 별개 로직이라 건드리지 않는다.
      if (/합계|소계|총계|누계/.test(c0) && !inst) continue;
      // 구분(c0) → 대출 성격.
      //  이 칸은 "정책자금(보증부)·일반은행·캐피탈"처럼 상품 종류를 적는 칸이라 법인/개인 축과 다르다.
      //  담당자가 성격(법인대출·대표자 개인대출·사업자대출)을 명시했을 때만 인정하고,
      //  아니면 미분류로 둔다. 현황표에는 채무자가 누구인지 적는 칸이 없어 회사 유형으로 추정하면
      //  대표자 개인 채무가 법인 부채비율에 섞여 들어간다.
      var kind = "";
      var k0 = norm(c0);
      if (k0) {
        LOAN_KINDS.forEach(function(K) { if (!kind && (k0.indexOf(norm(K.label)) >= 0 || k0.indexOf(norm(K.short)) >= 0)) kind = K.id; });
      }
      loans.push({ inst: inst, amount: amount, bank: bank, start: start, end: end, kind: kind, balance: balance });
    }
    if (loans.length > 0) { updates.loans = loans; auto.loans = true; }
  }

  // ── 나머지 항목 → company_info ────────────────────────────────────────
  //  ⚠️ 부채총계/자본총계/영업이익/이자비용은 computeFinanceRatios()가 이 라벨로 찾아
  //     부채비율·이자보상배율을 자동 계산한다. 라벨 문자열을 바꾸지 말 것.
  var infoItems = [];
  var addInfo = function(label, val) { if (val && String(val).trim()) infoItems.push({ label: label, value: String(val).trim() }); };
  // 매출 추이 표의 당기순이익 — 위에서 단위를 확정한 값만 담는다(부채총계 등과 같은 (원) 단위 항목)
  profitInfo.forEach(function(pi) { addInfo(pi.label, pi.value); });
  addInfo("부채총계", get("부채총계 (원)"));
  addInfo("자본총계", get("자본총계 (원)"));
  addInfo("영업이익", get("영업이익 (원)"));
  addInfo("이자비용", get("이자비용 (원)"));
  addInfo("재무제표 기준연도", get("재무제표 기준연도"));
  addInfo("최근 정책자금 수령", get("최근 정책자금 수령 기관 / 일자"));
  addInfo("기관 요건 판정", get("기관 요건 판정"));
  addInfo("대표자 생년월일", get("생년월일"));
  addInfo("지역 구분", get("지역 (수도권 / 비수도권)"));
  addInfo("주요취급품목", get("주요 취급품목"));
  addInfo("업력", get("업력 (년)"));
  addInfo("4대보험 가입인원", get("★ 4대보험 가입인원 (직전연도 기준)"));
  addInfo("세무사 연락처", get("세무사 연락처"));
  addInfo("법인 자본금", get("법인 자본금 (원)"));
  addInfo("신용 조회일", get("신용 조회일"));
  addInfo("추가 사업자 여부", get("추가 사업자 여부"));
  addInfo("회생 및 파산 이력", get("회생 / 파산 이력"));
  addInfo("재창업 조건 (폐업이력)", get("폐업 이력 (재창업)"));
  addInfo("세금/금융 연체", get("세금·4대보험·금융 연체"));
  addInfo("기업인증", get("노란우산 · 제로페이 · 내일채움"));
  addInfo("사업장 부동산 유무", get("사업장 부동산 (자가/임차)"));
  addInfo("보증금/월세", get("보증금 / 월세 (원)"));
  addInfo("대표자 거주지 부동산", get("대표자 거주지 부동산"));
  addInfo("대표이사 자산현황", get("대표이사 자산 (부동산 / 자동차)"));
  addInfo("대표 결혼 유/무", get("대표 결혼 유 / 무"));
  addInfo("신청 희망 기관", get("신청 희망 기관"));
  addInfo("신청 희망 금액", get("신청 희망 금액"));
  addInfo("필요자금 사용용도", get("자금 사용 용도 (구체적으로)"));
  addInfo("수출실적", get("수출 실적"));
  addInfo("기업인증(벤처·이노비즈·메인비즈)", get("기업 인증 (벤처·이노비즈·메인비즈)"));
  addInfo("연구소", get("연구소 / 전담부서"));
  addInfo("특허 및 상표권", get("특허 · 상표 · 디자인"));
  addInfo("주요 거래처", get("주요 거래처 (대기업·장기거래)"));
  addInfo("2026 신규 융자", get("★ 2026년 신규 융자 (올해 새로 받은 것)"));
  addInfo("카드론·현금서비스", get("카드론 · 현금서비스"));
  if (infoItems.length > 0) { updates.company_info = infoItems; auto.company_info = true; }

  // ── 11. 자유 메모 → 비고 메모 (스크립트 재료가 여기 다 들어 있다) ─────
  var freeStart = null;
  rows.forEach(function(row, r) {
    if (freeStart != null || !row) return;
    if (/자유\s*메모/.test(cellStr(row[0]))) freeStart = r;
  });
  var freeLines = [];
  if (freeStart != null) {
    for (var fr = freeStart + 1; fr < rows.length; fr++) {
      var frow = rows[fr];
      if (!frow) continue;
      if (/^\d+\s*\./.test(cellStr(frow[0]))) break;   // 다음 섹션 헤더
      var joined = frow.map(cellStr).filter(Boolean).join(" ").trim();
      if (joined) freeLines.push(joined);
    }
  }

  // ── 9. 대표자만 아는 것 → 비고 메모 ──────────────────────────────────
  var memoParts = [];
  var weak = get("정책자금 신청에 가장 불리한 약점 (솔직하게)");
  var good = get("최근 호재 · 특이사항 (신규계약·수주·설비)");
  if (weak) memoParts.push("[약점] " + weak);
  if (good) memoParts.push("[호재] " + good);
  if (freeLines.length) memoParts.push("[자유 메모]\n" + freeLines.join("\n"));
  if (rawNotes.length) memoParts.push("[원문 보존]\n" + rawNotes.join("\n"));
  if (memoParts.length) { updates.company_info_memo = memoParts.join("\n\n"); auto.company_info_memo = true; }

  // ── 10. 거절 이력 → 소통내역 텍스트로만 (기대출 행으로 자동 생성하지 않는다) ──
  //  실제 작성본에는 "기관/일자/거절 사유" 머리행 없이 섹션 제목 바로 아래에 내용을 적는 경우가 있어
  //  머리행이 없으면 섹션 제목으로 찾는다(예전엔 이 경우 거절 이력이 통째로 유실됐다).
  var rejHdr = null;
  rows.forEach(function(row, r) {
    if (rejHdr != null || !row) return;
    if (norm(row[0]) === norm("기관") && norm(row[3]) === norm("일자") && norm(row[5]) === norm("거절 사유")) rejHdr = r;
  });
  if (rejHdr == null) {
    rows.forEach(function(row, r) {
      if (rejHdr != null || !row) return;
      if (/거절\s*이력/.test(cellStr(row[0]))) rejHdr = r;
    });
  }
  var commParts = [];
  if (rejHdr != null) {
    for (var rr = rejHdr + 1; rr < rows.length; rr++) {
      var rrow = rows[rr];
      if (!rrow) continue;
      var ri = cellStr(rrow[0]), rd = cellStr(rrow[3]), rs = cellStr(rrow[5]);
      if (/^\d+\s*\./.test(ri)) break;                                  // 다음 섹션(자유 메모 등)까지 먹지 않도록
      if (norm(ri) === norm("기관") && norm(rd) === norm("일자")) continue; // 머리행은 건너뜀
      if (!ri && !rd && !rs) continue;
      commParts.push("거절 이력: " + [ri, rd, rs].filter(Boolean).join(" / "));
    }
  }

  // 법인/개인 유형은 위(기업체명·사업자등록번호 직후)에서 이미 판정했다.

  return { updates: updates, auto: auto, commText: commParts.join("\n"), issues: issues, notes: notes };
}

// 신규 통합 양식인지 판정 — 시트명에 의존하지 않고 고유 라벨이 몇 개 잡히는지로 본다.
//  (시트명만 보면 이름을 바꿨을 때 또 같은 장애가 난다)
function looksLikeHyeonhwangpyoV2(rows) {
  var norm = function(s) { return String(s || "").replace(/\s/g, "").replace(/[:：\-()（）·.,/★]/g, ""); };
  var MARKERS = ["기업체명", "재무제표 기준연도", "부채총계", "자본총계", "상시근로자", "신청 희망 기관", "기관 요건 판정"];
  var found = {};
  (rows || []).forEach(function(row) {
    if (!row) return;
    [0, 6].forEach(function(c) {
      var v = norm(row[c]);
      if (!v) return;
      MARKERS.forEach(function(m) { if (v.indexOf(norm(m)) >= 0) found[m] = true; });
    });
  });
  return Object.keys(found).length >= 3;
}

// 업로드 파일 디스패처 - 표준 기업현황표면 기존 파서, 아니면 범용 시트지 파서
//  공통 반환: { updates, auto, commText, kind }
async function parseUploadedSheet(file) {
  var XLSX = await ensureXLSX();
  var data = await file.arrayBuffer();
  var wb = await readUploadedWorkbook(data, { type: "array", cellDates: true });
  var hasGaeyo = wb.SheetNames.some(function(n) { return n.indexOf("기업개요") >= 0; });
  if (hasGaeyo) {
    // 표준 기업현황표: 기존 파서 그대로 사용(기업정보 항목은 기업정보 탭으로), 비고 메모는 소통내역 텍스트로도 제공
    var res = await parseHyeonhwangpyo(file);
    var commParts = [];
    if (res.updates.company_info_memo) commParts.push(res.updates.company_info_memo);
    return { updates: res.updates, auto: res.auto, commText: commParts.join("\n"), kind: "기업현황표", issues: res.issues || [], notes: res.notes || [] };
  }
  // 신규 통합 양식(시트명 "정보시트" 등) — 구 양식과 레이아웃이 완전히 달라 전용 파서 사용.
  //  범용 파서로 넘어가면 4개 항목만 인식되고 값까지 오염된다(2026-07-27 진단).
  var wsV2 = wb.Sheets[wb.SheetNames.find(function(n) { return n.indexOf("정보시트") >= 0; }) || wb.SheetNames[0]];
  var rowsV2 = XLSX.utils.sheet_to_json(wsV2, { header: 1, defval: null });
  if (looksLikeHyeonhwangpyoV2(rowsV2)) {
    var v2 = parseHyeonhwangpyoV2(rowsV2);
    var v2Comm = [];
    if (v2.commText) v2Comm.push(v2.commText);
    if (v2.updates.company_info_memo) v2Comm.push(v2.updates.company_info_memo);
    return { updates: v2.updates, auto: v2.auto, commText: v2Comm.join("\n"), kind: "기업현황표(신규양식)", issues: v2.issues || [], notes: v2.notes || [] };
  }
  // 그 외: 첫 시트를 범용 파싱
  var ws = wb.Sheets[wb.SheetNames[0]];
  var rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: null });
  var g = parseSheetGeneric(rows);
  return { updates: g.updates, auto: g.auto, commText: g.commText, kind: "시트지", issues: [], notes: [] };
}

