    var body = (w ? m[2].replace(ITEM_WAIT_RE, "") : m[2]).replace(CARRIED_TAIL_RE, "").replace(/\s*$/, "");
    lines[i] = m[1] + "- [ ] " + body + " (→ " + md + " 이월)" + (waitTail ? " " + waitTail : "");
